                () -> callStatus(post("/api/declarations/DECL-CW/versions/1/withdraw")
                        .header("X-Actor-Id", "sup-1")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"CK-CW-W\"}")),
