        int approval = results.get(1).get(30, TimeUnit.SECONDS);
        assertEquals(200, withdraw, "撤回始终成功且只影响后续放行");
        Integer snapshots = jdbc.queryForObject(
                "SELECT COUNT(*) FROM release_snapshot WHERE batch_key = ?",
                Integer.class, batchKey);
